// ---------------------------------------------------------------------------
// Entity layout – adjust offsets to match your game's memory layout
// ---------------------------------------------------------------------------
struct EntityRecord
{
    float x, y, z;       // world-space position
    float health;
    int   team;          // 0 = player, 1 = enemy, 2 = neutral
    bool  alive;
};

// Hypothetical in-process entity list (replace with real scan / module offset)
struct GameState
{
    uint32_t     entityCount;        // number of live slots
    EntityRecord entities[256];      // flat array in the same process
};

// ---------------------------------------------------------------------------
// Memory reader – operates on this process only (ReadProcessMemory on self)
// ---------------------------------------------------------------------------
class SelfMemoryReader
{
public:
    explicit SelfMemoryReader(const void* baseAddress)
        : m_base(reinterpret_cast<uintptr_t>(baseAddress)) {}

    bool readEntities(std::vector<EntityRecord>& out) const
    {
        const auto* gs = reinterpret_cast<const GameState*>(m_base);
        SIZE_T      bytesRead = 0;
        GameState   local{};

        BOOL ok = ReadProcessMemory(
            GetCurrentProcess(),
            gs,
            &local,
            sizeof(local),
            &bytesRead);

        if (!ok || bytesRead < sizeof(local))
            return false;

        const uint32_t count = (local.entityCount < 256u) ? local.entityCount : 256u;
        out.assign(local.entities, local.entities + count);
        return true;
    }

private:
    uintptr_t m_base;
};

